rss.channel:
      {{ config.title }}
        {%- if term %} - {{ term.name }}
        {%- elif section and section.title %} - {{ section.title }}
        {%- endif -%}


        {%- if section -%}
          {{ section.permalink | escape_xml | safe }}
        {%- else -%}
          {{ config.base_url | escape_xml | safe }}
        {%- endif -%}

      {{ config.description }}
      Zola
      {{ get_url(path="info") }}
      {{ lang }}

      {% if last_updated is defined %}{{ last_updated | date(format="%a, %d %b %Y %H:%M:%S %z") }}{% endif %}
      {%- for page in pages %}


	  {%- if page.components[0] == "today" -%}
              ⭐ TODAY: {{ page.title }}
	  {%- elif page.extra.scheduled_date is defined -%}
              {{ page.extra.scheduled_date | date(timezone=config.extra.TZ, format="%A %-m/%-e") }}: {{ page.title }}
	  {%- else -%}
	    {{ page.title }}
	  {%- endif -%}
          {{ page.date | date(format="%a, %d %b %Y %H:%M:%S %z") }}

            {%- if page.authors -%}
              {{ page.authors[0] }}
            {%- elif config.author -%}
              {{ config.author }}
            {%- else -%}
              Unknown
            {%- endif -%}

          {{ page.permalink | escape_xml | safe }}
          {{ page.extra.uuid }}
          {{ page.content }}

      {%- endfor %}
